#!/usr/bin/env bats

# Tests for topips.sh against the deterministic log produced by gen.sh.
#
# Documented tie-breaking rule: equal counts are ordered by ascending IP
# (lexicographic). gen.sh produces a tie at 90 between 172.16.0.5 and
# 172.16.0.6, so 172.16.0.5 must appear before 172.16.0.6.

setup() {
    TOPIPS="$BATS_TEST_DIRNAME/topips.sh"
    GEN="$BATS_TEST_DIRNAME/gen.sh"
    LOG="$BATS_TEST_TMPDIR/sample.log"
    "$GEN" "$LOG" > /dev/null
}

@test "gen.sh produces exactly 500 lines" {
    [ "$(wc -l < "$LOG")" -eq 500 ]
}

@test "topips prints the exact top 3 lines from the generated log" {
    run bash -c "'$TOPIPS' '$LOG' | head -n 3"
    [ "$status" -eq 0 ]
    expected='150 10.0.0.1
120 192.168.1.10
90 172.16.0.5'
    [ "$output" = "$expected" ]
}

@test "tie at count 90 is broken by ascending IP (172.16.0.5 before 172.16.0.6)" {
    run "$TOPIPS" "$LOG"
    tie_lines=$(printf '%s\n' "$output" | grep '^90 ')
    [ "$tie_lines" = '90 172.16.0.5
90 172.16.0.6' ]
    line3=$(printf '%s\n' "$output" | sed -n '3p')
    line4=$(printf '%s\n' "$output" | sed -n '4p')
    [ "$line3" = '90 172.16.0.5' ]
    [ "$line4" = '90 172.16.0.6' ]
}

@test "counts are printed first, in descending order, over the whole output" {
    run bash -c "'$TOPIPS' '$LOG' | awk '{print \$1}'"
    expected='150
120
90
90
30
20'
    [ "$output" = "$expected" ]
}

@test "missing file exits 2 with usage message on stderr" {
    run "$TOPIPS" "$BATS_TEST_TMPDIR/does-not-exist.log"
    [ "$status" -eq 2 ]
    [[ "$output" == *"usage:"*"$TOPIPS LOGFILE"* ]]
}

@test "no arguments exits 2 with usage on stderr" {
    run "$TOPIPS"
    [ "$status" -eq 2 ]
    [[ "$output" == *"usage:"* ]]
}

@test "output never exceeds 10 lines even with many distinct IPs" {
    many="$BATS_TEST_TMPDIR/many.log"
    for i in $(seq 1 25); do
        ip="10.1.$(( i / 256 )).$(( i % 256 ))"
        for _ in $(seq 1 $(( 26 - i ))); do
            echo "$ip - - [24/Aug/2026:00:00:00 +0000] \"GET / HTTP/1.1\" 200 -" >> "$many"
        done
    done
    lines=$("$TOPIPS" "$many" | wc -l)
    [ "$lines" -eq 10 ]
}

